import * as React from "react"
import Header from "./Header"
import { ArrowRight, Check } from "./Icons"
import * as s from "./Outcome.module.css"

/**
 * The page somebody lands on after leaving for Stripe — success or cancelled.
 *
 * Both outcomes share a shape because both are the same moment: they have come
 * back from somewhere else and need to know, in the first line, what happened
 * and what to do next. A cancelled checkout is NOT an error and is not dressed
 * as one — nothing was charged, the site is still there, and the only sensible
 * next action is going back to it.
 */
const Outcome = ({ tone = "success", title, lead, points, primary, secondary }) => (
  <>
    <Header />
    <main className={s.page} data-print="hide">
      <div className="container">
        <div className={`${s.card} ${tone === "success" ? s.success : s.neutral}`}>
          <span className={s.mark} aria-hidden="true">
            {tone === "success" ? (
              <Check style={{ width: 34, height: 34 }} />
            ) : (
              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                <circle cx="12" cy="12" r="10" />
                <path d="M12 7v6M12 16.5v.01" />
              </svg>
            )}
          </span>

          <h1 className={s.title}>{title}</h1>
          <p className={s.lead}>{lead}</p>

          {points && points.length > 0 ? (
            <ul className={`checks ${s.points}`}>
              {points.map(point => (
                <li key={point}>
                  <Check />
                  {point}
                </li>
              ))}
            </ul>
          ) : null}

          <div className={s.actions}>
            <a href={primary.href} className="btn btn--lg">
              {primary.label}
              <ArrowRight className="btn__arrow" />
            </a>
            {secondary ? (
              <a href={secondary.href} className={s.secondary}>
                {secondary.label}
              </a>
            ) : null}
          </div>
        </div>
      </div>
    </main>
  </>
)

export default Outcome
