import * as React from "react"
import Outcome from "../../components/Outcome"
import Seo from "../../components/Seo"

/**
 * Back from an abandoned Stripe checkout.
 *
 * A cancelled payment is not a failure and is not dressed as one. The single
 * most useful fact is that nothing was charged and nothing was lost, so that
 * is the first line — followed by the one action that matters, which is
 * getting back to the site they already built.
 */
const CancelledPage = () => (
  <Outcome
    tone="neutral"
    title="No payment was taken"
    lead="You left checkout before paying, so nothing was charged. Your website is exactly as you left it — pick it back up whenever you are ready."
    points={[
      "Your draft is saved in this browser",
      "Nothing has been published",
      "No card details were entered or stored",
    ]}
    primary={{ href: "/website-builder", label: "Back to my website" }}
    secondary={{ href: "/", label: "Return home" }}
  />
)

export const Head = () => <Seo title="Checkout cancelled" />

export default CancelledPage
